const productId = $('Create a product').first().json.id;
const imgbb = $('Upload to ImgBB').first().json?.data;
const imageSrc = imgbb?.image?.url || imgbb?.url || imgbb?.display_url || '';

const sourceItems = $input.all();
if (!sourceItems[0]?.binary?.data) {
  throw new Error(`No image binary from Download ImgBB for Shopify. URL: ${imageSrc}`);
}

const buffer = await this.helpers.getBinaryDataBuffer(0, 'data', sourceItems);

function detectImageExt(buf) {
  if (!buf?.length) return null;
  if (buf[0] === 0x89 && buf[1] === 0x50) return 'png';
  if (buf[0] === 0xff && buf[1] === 0xd8) return 'jpg';
  if (buf[0] === 0x47 && buf[1] === 0x49) return 'gif';
  if (buf.length > 12 && buf.slice(0, 4).toString() === 'RIFF' && buf.slice(8, 12).toString() === 'WEBP') return 'webp';
  return null;
}

const ext = detectImageExt(buffer);
if (!ext) {
  throw new Error(`Downloaded file is not a valid image (${buffer.slice(0, 16).toString('hex')}) from ${imageSrc}`);
}

const binaryMeta = sourceItems[0].binary.data;
const filename = binaryMeta.fileName || (binaryMeta.fileExtension ? `product.${binaryMeta.fileExtension}` : `product.${ext}`);

return [{
  json: {
    product_id: productId,
    attachment: buffer.toString('base64'),
    filename,
    image_src: imageSrc,
    bytes: buffer.length,
  },
}];

const upload = $input.first().json;
const productId = $('Create a product').first().json.id;
const imgbb = $('Upload to ImgBB').first().json?.data;
const imgbbUrl = imgbb?.image?.url || imgbb?.url || imgbb?.display_url || '';
const src = upload?.image?.src ?? '';
const shopifyImageUrl = src || imgbbUrl;
const onShopifyCdn = src.includes('cdn.shopify.com') || src.includes('shopifycdn.com');

return [{
  json: {
    product_id: productId,
    shopify_image_url: shopifyImageUrl,
    shopify_image_ready: onShopifyCdn,
    image_source: onShopifyCdn ? 'shopify_cdn' : (src ? 'shopify_attachment' : 'imgbb_fallback'),
  },
}];

const row = $('Validate sheet row').first().json;
const http = $input.first().json;
const productUrl = row.source_product_url || row['Product URL'] || '';
let body = http.data ?? http.body ?? '';

if (typeof body !== 'string') {
  try { body = JSON.stringify(body); } catch { body = String(body); }
}

function extractJsonLd(html) {
  const out = [];
  const re = /<script[^>]*type=["']application\/ld\+json["'][^>]*>([\s\S]*?)<\/script>/gi;
  let m;
  while ((m = re.exec(html)) !== null) {
    try { out.push(JSON.parse(m[1])); } catch { /* skip */ }
  }
  return out;
}

function meta(html, prop) {
  const re = new RegExp(`<meta[^>]+(?:property|name)=["']${prop}["'][^>]+content=["']([^"']+)["']`, 'i');
  const m = html.match(re);
  return m ? m[1] : '';
}

const jsonLd = extractJsonLd(body);
const snippet = {
  product_url: productUrl,
  run_id: row._run_id,
  json_ld: jsonLd.slice(0, 3),
  og_title: meta(body, 'og:title'),
  og_description: meta(body, 'og:description'),
  og_image: meta(body, 'og:image'),
  html_excerpt: body.replace(/<script[\s\S]*?<\/script>/gi, '').replace(/\s+/g, ' ').slice(0, 12000),
};

return [{ json: { ...row, scrape_context: snippet } }];

