const row = $('Prepare page for scrape').first().json;
const ai = $input.first().json;
let text = ai.output?.[0]?.content?.[0]?.text || ai.text || ai.message?.content || '';
text = String(text).replace(/```json|```/g, '').trim();
let scraped;
try {
  scraped = JSON.parse(text);
} catch (e) {
  throw new Error(`AI scrape returned invalid JSON: ${text.slice(0, 300)}`);
}

const category = scraped.product_category || scraped.category || row.validated_category || '';
let sku = String(row.SKU || row.validated_sku || row.processing_sku || '').trim();
if (!sku) sku = generateSku(category);
const competitorPrice = scraped.competitor_price ?? scraped.price ?? scraped.variant_price ?? '';
const competitorCurrency = scraped.competitor_currency ?? scraped.currency ?? '';
const imageUrl = scraped.image_url || scraped.product_image_url || row.validated_image_url;
const title = scraped.title || row.Title || '';
const description = scraped.description_plain || scraped.description || row.Description || '';
const vendor = scraped.vendor || scraped.brand || row.validated_vendor || '';
const tags = scraped.tags || '';
const sizes = Array.isArray(scraped.sizes) ? scraped.sizes.join(', ') : String(scraped.sizes || '');
const colors = Array.isArray(scraped.colors) ? scraped.colors.join(', ') : String(scraped.colors || '');
const scrapedVariants = JSON.stringify(scraped.variants || []);
// Sell price + stock: SHEET ONLY (you set after you know margin / order qty)
const sheetPrice = row['Price'] ?? row.validated_price;
const sellPrice = sheetPrice === '' || sheetPrice === null || sheetPrice === undefined ? null : String(sheetPrice);
const sheetInv = row['Inventory quantity'] ?? row.validated_inventory;
const inventory = sheetInv === '' || sheetInv === null || sheetInv === undefined ? null : Number(sheetInv);

return [{
  json: {
    ...row,
    Title: title,
    Description: description,
    'Product image URL': imageUrl,
    'Competitor price': competitorPrice,
    'Competitor currency': competitorCurrency,
    Sizes: sizes,
    Colors: colors,
    'Scraped variants': scrapedVariants,
    Vendor: vendor,
    'Product category': category,
    Tags: tags,
    SKU: sku,
    'Scrape Status': 'SCRAPED',
    'Source Product URL': row.source_product_url,
    scraped_raw_description: description,
    validated_image_url: imageUrl,
    validated_raw_info: description || title,
    validated_category: category,
    validated_vendor: vendor,
    validated_price: sellPrice,
    validated_sku: sku,
    validated_inventory: inventory,
    needs_scrape: false,
  },
}];

const v = $('Validate sheet row').first().json;
let merged = { ...v };
try {
  const scraped = $('Apply scraped data').first().json;
  if (scraped?.validated_sku) merged = { ...merged, ...scraped };
} catch { /* scrape branch did not run */ }

if (!merged.validated_image_url) {
  merged.validated_image_url = merged['Product image URL'] || '';
}
if (!merged.validated_raw_info) {
  merged.validated_raw_info = merged.Description || merged.Title || '';
}

// Sell price + stock: SHEET ONLY — competitor price is reference only
const sheetPrice = merged['Price'] ?? merged['Variant Price'] ?? merged.validated_price;
merged.validated_price = sheetPrice === '' || sheetPrice === null || sheetPrice === undefined ? null : String(sheetPrice);
const sheetInv = merged['Inventory quantity'] ?? merged['Variant Inventory Qty'] ?? merged.validated_inventory;
merged.validated_inventory = sheetInv === '' || sheetInv === null || sheetInv === undefined ? 0 : Number(sheetInv);

// Per-field AI prompts (optional sheet columns override defaults)
const defaults = {
  title: 'Write a completely NEW original title. Same product facts but different words. Never copy competitor phrasing. Max 70 chars UK fashion.',
  description: 'Rewrite in your own words — new sentences only. Keep factual specs (material, fit, colour). Do NOT copy competitor text (copyright). HTML <p> tags.',
  tags: 'Original search tags only — not copied from source. Max 10 UK fashion keywords.',
  seo_title: 'Original Google title, max 60 chars. Paraphrase — do not copy source.',
  seo_description: 'Original meta description, max 160 chars. New wording, same facts.',
  image_alt_text: 'Original alt text describing what you see in the image.',
  collection: 'UK fashion category path e.g. Men > Shirts > Casual',
};
const pick = (col, key) => String(merged[col] || merged[`Prompt: ${key}`] || '').trim() || defaults[key];
merged.ai_field_prompts = {
  title: pick('Prompt Title', 'title'),
  description: pick('Prompt Description', 'description'),
  tags: pick('Prompt Tags', 'tags'),
  seo_title: pick('Prompt SEO title', 'seo_title'),
  seo_description: pick('Prompt SEO description', 'seo_description'),
  image_alt_text: pick('Prompt Image alt', 'image_alt_text'),
  collection: pick('Prompt Category', 'collection'),
};

merged._run_id = merged._run_id || `${Date.now()}-${merged.processing_sku}`;
return [{ json: merged }];

const THRESHOLDS = {
  maxConsecutiveWords: 7,
  phraseOverlapPercent: 25,
  jaccardTitle: 0.45,
  jaccardDescription: 0.50,
};

function normalizeText(t) {
  return String(t || '')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&[a-z]+;/gi, ' ')
    .replace(/[^\w\s]/g, ' ')
    .toLowerCase()
    .split(/\s+/)
    .filter((w) => w.length > 1);
}

function jaccardSimilarity(wordsA, wordsB) {
  const setA = new Set(wordsA);
  const setB = new Set(wordsB);
  if (setA.size === 0 && setB.size === 0) return 0;
  let inter = 0;
  for (const w of setA) if (setB.has(w)) inter++;
  const union = new Set([...setA, ...setB]).size;
  return union === 0 ? 0 : inter / union;
}

function maxConsecutiveWordMatch(orig, gen) {
  let max = 0;
  for (let i = 0; i < orig.length; i++) {
    for (let j = 0; j < gen.length; j++) {
      let k = 0;
      while (i + k < orig.length && j + k < gen.length && orig[i + k] === gen[j + k]) k++;
      if (k > max) max = k;
    }
  }
  return max;
}

function phraseOverlapPercent(origWords, genWords, n) {
  if (genWords.length < n || origWords.length < n) return 0;
  const origText = origWords.join(' ');
  let matched = 0;
  let total = 0;
  for (let i = 0; i <= genWords.length - n; i++) {
    total++;
    const phrase = genWords.slice(i, i + n).join(' ');
    if (origText.includes(phrase)) matched++;
  }
  return total === 0 ? 0 : Math.round((matched / total) * 100);
}

const row = $('Active product row').first().json;
const aiRaw = $('AI write listing').first().json;
let text = aiRaw.output?.[0]?.content?.[0]?.text || aiRaw.text || '';
text = String(text).replace(/```json|```/g, '').trim();
let listing;
try {
  listing = JSON.parse(text);
} catch (e) {
  throw new Error(`Cannot parse AI write listing for overlap check: ${text.slice(0, 200)}`);
}

const originalTitle = row.Title || '';
const originalDesc = row.scraped_raw_description || row.Description || '';
const generatedTitle = listing.title || '';
const generatedDesc = listing.description_html || listing.description || '';

const origTitleW = normalizeText(originalTitle);
const origDescW = normalizeText(originalDesc);
const genTitleW = normalizeText(generatedTitle);
const genDescW = normalizeText(generatedDesc);

const titleJaccard = Math.round(jaccardSimilarity(origTitleW, genTitleW) * 100);
const descJaccard = Math.round(jaccardSimilarity(origDescW, genDescW) * 100);
const titlePhrase = phraseOverlapPercent(origTitleW, genTitleW, 4);
const descPhrase = phraseOverlapPercent(origDescW, genDescW, 5);
const maxConsecutive = Math.max(
  maxConsecutiveWordMatch(origTitleW, genTitleW),
  maxConsecutiveWordMatch(origDescW, genDescW),
);

const reasons = [];
if (maxConsecutive >= THRESHOLDS.maxConsecutiveWords) {
  reasons.push(`${maxConsecutive} consecutive words match source (limit ${THRESHOLDS.maxConsecutiveWords - 1})`);
}
if (descPhrase >= THRESHOLDS.phraseOverlapPercent) {
  reasons.push(`Description 5-word phrase overlap ${descPhrase}% (limit ${THRESHOLDS.phraseOverlapPercent - 1}%)`);
}
if (titlePhrase >= THRESHOLDS.phraseOverlapPercent) {
  reasons.push(`Title 4-word phrase overlap ${titlePhrase}%`);
}
if (titleJaccard / 100 >= THRESHOLDS.jaccardTitle) {
  reasons.push(`Title Jaccard word overlap ${titleJaccard}%`);
}
if (descJaccard / 100 >= THRESHOLDS.jaccardDescription) {
  reasons.push(`Description Jaccard word overlap ${descJaccard}%`);
}

const overlap_fail = reasons.length > 0;
const overlap_percent = Math.max(descPhrase, titlePhrase, descJaccard, titleJaccard);

return [{
  json: {
    listing,
    overlap_title_jaccard_pct: titleJaccard,
    overlap_desc_jaccard_pct: descJaccard,
    overlap_title_phrase_pct: titlePhrase,
    overlap_desc_phrase_pct: descPhrase,
    overlap_max_consecutive_words: maxConsecutive,
    overlap_percent,
    overlap_fail,
    overlap_reasons: reasons,
    overlap_summary: overlap_fail ? reasons.join('; ') : 'OK — sufficient paraphrase',
  },
}];
